49	/** A JSON-RPC level error returned by the Storybook MCP server (e.g. unknown tool). */
50	export class McpJsonRpcError extends Error {
51	  constructor(
52	    public readonly code: number,
53	    message: string
54	  ) {
55	    super(`Storybook server error ${code}: ${message}`);
56	    this.name = 'McpJsonRpcError';
57	  }
58	}
